from decimal import Decimal, ROUND_HALF_UP


def _value(row: dict, key: str) -> str:
    value = row.get(key, "")
    return "" if value is None else str(value)


def _fixed(value: str, width: int) -> str:
    return value[:width].ljust(width)


def _zpad_cents(value: str, width: int) -> str:
    amount = Decimal(value) if value != "" else Decimal(0)
    cents = (amount * Decimal(100)).quantize(
        Decimal(1),
        rounding=ROUND_HALF_UP,
    )
    return str(int(cents)).zfill(width)


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT fixed-width record."""
    acct_id = _fixed(_value(row, "ACCT_ID"), 10)
    acct_nm = _fixed(_value(row, "ACCT_NM"), 40)
    region_cd = _fixed(_value(row, "REGION_CD"), 3)
    ann_rev = _zpad_cents(_value(row, "ANN_REV"), 15)

    cred_hold = _value(row, "CRED_HOLD")
    if cred_hold == "":
        cred_hold = "N"

    create_dt = _value(row, "CREATE_DT")
    if create_dt == "":
        create_dt = "00000000"

    return acct_id + acct_nm + region_cd + ann_rev + cred_hold + create_dt
